import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Proposizione controinversa","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/k_logica/kb/kbnbd.md","filePath":"lezioni/k_logica/kb/kbnbd.md"}`),a={name:`lezioni/k_logica/kb/kbnbd.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="proposizione-controinversa" tabindex="-1">Proposizione controinversa <a class="header-anchor" href="#proposizione-controinversa" aria-label="Permalink to “Proposizione controinversa”">​</a></h1><p>Chiameremo <strong>proposizione controinversa</strong> la proposizione ottenuta prendendo le negazioni dell&#39;ipotesi e della tesi e scambiandone le posizioni:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>Se\xA0non\xA0Tesi\xA0allora\xA0non\xA0Ipotesi</mtext></mrow><annotation encoding="application/x-tex">\\text{Se non Tesi allora non Ipotesi} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">Se\xA0non\xA0Tesi\xA0allora\xA0non\xA0Ipotesi</span></span></span></span></span></span></p><p>La proposizione controinversa è sempre vera;</p><blockquote><p><strong>Esempio:</strong></p><p>Dal teorema precedente</p><p><strong>Se un numero è divisibile per <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>4</mn></mrow><annotation encoding="application/x-tex">4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span> allora il numero è pari</strong></p><p>Neghiamo l&#39;ipotesi ed anche la tesi e scambiamole di posto; ottengo:</p><p><strong>Se un numero non è pari allora il numero non è divisibile per <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>4</mn></mrow><annotation encoding="application/x-tex">4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span></strong></p><p>È vero: un numero pari per definizione è divisibile per <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn></mrow><annotation encoding="application/x-tex">2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span>; se non è pari allora non è divisibile per <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn></mrow><annotation encoding="application/x-tex">2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> e quindi non è neppure divisibile per <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>4</mn></mrow><annotation encoding="application/x-tex">4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span>.</p></blockquote>`,5)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};